mapper.select:
WITH virtualInventoryDetailHis AS ( select vidh.date, vid.sku_id, vid.warehouse_id, vid.virtual_warehouse_id, sum(vidh.wait_qty * vidh.inventory_age_days) as inventoryAgeQty from virtual_inventory_detail_his vidh left join virtual_inventory_detail vid on vidh.virtual_inventory_detail_id = vid.id and vid.is_deleted = false where vidh.is_deleted = false and vid.sku_id = #{dto.skuId} and vid.warehouse_id = #{dto.warehouseId} and vid.virtual_warehouse_id = #{dto.virtualWarehouseId}
and vidh.date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > vidh.date
group by vid.sku_id,vid.warehouse_id,vid.virtual_warehouse_id,vidh.date ),VirtualInventoryHis AS ( SELECT vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id, SUM(vih.qty) AS virtualQty, SUM(CASE WHEN vi.dict_inventory_status = 'usable' THEN vih.qty ELSE 0 END) AS virtualUsableQty, SUM(CASE WHEN vi.dict_inventory_status = 'frozen' THEN vih.qty ELSE 0 END) AS virtualFrozenQty FROM virtual_inventory_his vih left join virtual_inventory vi on vih.virtual_inventory_id = vi.id and vi.is_deleted = false WHERE vih.is_deleted = false and vi.sku_id = #{dto.skuId} and vi.warehouse_id = #{dto.warehouseId} and vi.virtual_warehouse_id = #{dto.virtualWarehouseId}
and vih.date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > vih.date
GROUP BY vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id ) select vidh.date, vidh.sku_id, pd.sku_no, pd.name as productName, vidh.warehouse_id, wh.name as warehouseName, vidh.virtual_warehouse_id, vw.name as virtualWarehouseName, case when vih.virtualQty = 0 then 0 else vidh.inventoryAgeQty / virtualQty end as avgInventoryAgeDays, vih.virtualQty, vih.virtualUsableQty , vih.virtualFrozenQty from virtualInventoryDetailHis vidh left join VirtualInventoryHis vih on vidh.sku_id = vih.sku_id and vidh.warehouse_id = vih.warehouse_id and vidh.virtual_warehouse_id = vih.virtual_warehouse_id left join product_detail pd on vih.sku_id = pd.id and pd.is_deleted = false left join warehouse wh on vih.warehouse_id = wh.id and wh.is_deleted = false left join virtual_warehouse vw on vih.virtual_warehouse_id = vw.id and vw.is_deleted = false order by vidh.date asc

select vhd.batch_no, vtf.trade_time, vtf.transaction_no, vtf.source_type, vtf.source_code, vtf.dict_inventory_status, vidh.qty as batchQty, vidh.wait_qty as waitBatchQty, vidh.inventory_age_days, vidh.update_time from virtual_inventory_detail_his vidh inner join virtual_inventory_detail vhd on vidh.virtual_inventory_detail_id = vhd.id and vhd.is_deleted = false inner join virtual_trans_flow vtf on vtf.id = vhd.virtual_trans_flow_id and vtf.is_deleted = false
vidh.is_deleted = false and vidh.wait_qty > 0 and vhd.sku_id = #{params.skuId} and vhd.warehouse_id = #{params.warehouseId} and vhd.virtual_warehouse_id = #{params.virtualWarehouseId}
and vidh.date = #{params.date}
and vidh.inventory_age_days > #{params.daysList[0]}
and #{params.dateList[1] >= #{params.daysList[1]}
order by vtf.trade_time desc

WITH virtualInventoryDetailHis AS ( select vidh.date, vid.sku_id, vid.warehouse_id, vid.virtual_warehouse_id, sum(vidh.wait_qty * vidh.inventory_age_days) as inventoryAgeQty from virtual_inventory_detail_his vidh left join virtual_inventory_detail vid on vidh.virtual_inventory_detail_id = vid.id and vid.is_deleted = false where vidh.is_deleted = false and vid.sku_id = #{params.skuId} and vid.warehouse_id = #{params.warehouseId} and vid.virtual_warehouse_id = #{params.virtualWarehouseId}
and vidh.date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > vidh.date
group by vid.sku_id,vid.warehouse_id,vid.virtual_warehouse_id,vidh.date ),VirtualInventoryHis AS ( SELECT vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id, SUM(vih.qty) AS virtualQty, SUM(CASE WHEN vi.dict_inventory_status = 'usable' THEN vih.qty ELSE 0 END) AS virtualUsableQty, SUM(CASE WHEN vi.dict_inventory_status = 'frozen' THEN vih.qty ELSE 0 END) AS virtualFrozenQty FROM virtual_inventory_his vih left join virtual_inventory vi on vih.virtual_inventory_id = vi.id and vi.is_deleted = false WHERE vih.is_deleted = false and vi.sku_id = #{params.skuId} and vi.warehouse_id = #{params.warehouseId} and vi.virtual_warehouse_id = #{params.virtualWarehouseId}
and vih.date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > vih.date
GROUP BY vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id ) select vidh.date, case when vih.virtualQty = 0 then 0 else vidh.inventoryAgeQty / virtualQty end as avgInventoryAgeDays from virtualInventoryDetailHis vidh left join VirtualInventoryHis vih on vidh.sku_id = vih.sku_id and vidh.warehouse_id = vih.warehouse_id and vidh.virtual_warehouse_id = vih.virtual_warehouse_id order by vidh.date asc

select vtf.sku_id, pd.sku_no, pd.name as productName, wh.name as warehouseName, vw.code as virtualWarehouseCode, vw.name as virtualWarehouseName, vtf.transaction_no, vid.batch_no, vid.bill_date, vtf.source_type, vtf.source_code, vtf.dict_inventory_status, vtfd.qty as batchQty, vid.qty as waitBatchQty, vid.last_outstock_date, vid.update_time from virtual_trans_flow_detail vtfd inner join virtual_trans_flow vtf on vtf.id = vtfd.virtual_trans_flow_id and vtf.is_deleted = false inner join virtual_inventory_detail vid on vtfd.virtual_inventory_detail_id = vid.id and vid.is_deleted = false left join product_detail pd on vtf.sku_id = pd.id and pd.is_deleted = false left join warehouse wh on vtf.warehouse_id = wh.id and wh.is_deleted = false left join virtual_warehouse vw on vtf.virtual_warehouse_id = vw.id and vw.is_deleted = false
vtfd.is_deleted = false vtf.sku_id = #{params.skuId} and vtfdwarehouse_id = #{params.warehouseId} and vtfd.virtual_warehouse_id = #{params.virtualWarehouseId}
and vtfd.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > vtfd.trade_time

select

from virtual_inventory_detail vid

    vid.is_deleted = false and vid.qty > 0 and vid.sku_id = #{skuId}
    and vid.warehosue_id = #{warehouseId} and vid.virtual_warehouse_id = #{virtualWarehouseId}

order by vid.bill_date asc
